create role anon; create role authenticated; create role service_role bypassrls;
create role authenticator login password 'local-dev-only' noinherit;
grant anon,authenticated,service_role to authenticator;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claims',true)::jsonb->>'sub','')::uuid$$;

grant usage on schema auth to authenticated,service_role;
create table public.indai_private_config(name text primary key,value text);
create table public.indai_tv_bars(ticker text,t bigint,o numeric,h numeric,l numeric,c numeric,v numeric,tf text,received_at timestamptz default now(),primary key(ticker,t));
create table public.indai_tv_alerts(id bigint generated by default as identity primary key,received_at timestamptz default now(),ticker text,kind text,text text,price numeric,levels jsonb,payload jsonb);
create table public.indai_memory(id bigint generated by default as identity primary key, text text not null, kind text default 'note',created_at timestamptz default now());
insert into public.indai_memory(text,kind) values ('One private pre-migration rule','learned');
insert into public.indai_private_config values ('tv_webhook_key','local-fixture');
alter default privileges in schema public grant all on tables to anon,authenticated,service_role;
alter default privileges in schema public grant all on sequences to anon,authenticated,service_role;
grant usage,select on all sequences in schema public to service_role;
-- Isolated stand-ins for the three hosted extensions. No outgoing scheduler traffic.
create schema vault;create table vault.secrets(id uuid default gen_random_uuid(),name text,secret text);
create view vault.decrypted_secrets as select name,secret as decrypted_secret from vault.secrets;
create function vault.create_secret(text,text) returns uuid language sql as $$insert into vault.secrets(secret,name) values($1,$2) returning id$$;
create schema cron;create table cron.job(jobid bigint generated by default as identity,jobname text unique,schedule text,command text);
create function cron.schedule(text,text,text) returns bigint language sql as $$insert into cron.job(jobname,schedule,command) values($1,$2,$3) on conflict(jobname) do update set schedule=excluded.schedule,command=excluded.command returning jobid$$;
create schema net;create table net._http_response(id bigint,timed_out boolean,error_msg text,status_code int);
create table net.requests(id bigint generated by default as identity,url text,headers jsonb,body jsonb);
create function net.http_post(url text,body jsonb default '{}',params jsonb default '{}',headers jsonb default '{}',timeout_milliseconds integer default 2000) returns bigint language sql as $$insert into net.requests(url,body,headers) values($1,$2,$4) returning id$$;
